              <a
                key={link.name}
                href={link.href}
                onClick={() => setIsOpen(false)}
                className="block px-3 py-3 text-base font-medium text-slate-700 hover:text-brand-600 hover:bg-slate-50 rounded-md"
              >
                {link.name}
              </a>
            ))}
             <a
              href="#register"
              onClick={() => setIsOpen(false)}
              className="block mt-4 text-center px-3 py-3 text-base font-bold bg-brand-600 text-white rounded-md hover:bg-brand-700"
